"""Config for wc: one TOML file, generated by `wc setup`, never hand-written first.

Transcription speaks the OpenAI audio-transcriptions shape
(POST multipart: file + model, Authorization: Bearer, JSON {"text": ...}),
which most ASR services and local servers implement. Providers that deviate
are declared as ADAPTERS - data, not code:

    ADAPTERS = {"deepgram": {"path": "/listen", "response_path": [...]}}

Adding a provider is an entry in that dict (or a [transcription.adapters.*]
block in the file), never a new class.
"""

import json
import os
import tomllib
from dataclasses import dataclass, field
from pathlib import Path

def home_dir() -> Path:
    """Read CUFF_HOME at call time - tests and `cuff --home` must not need a re-import."""
    return Path(os.environ.get("CUFF_HOME", Path.home() / ".wrist"))


def config_path() -> Path:
    return home_dir() / "config.toml"

# Deviations from the audio-transcriptions shape, declared as data.
ADAPTERS = {
    "deepgram": {
        "path": "/listen",
        "response_path": ["results", "channels", 0, "alternatives", 0, "transcript"],
    },
    "assemblyai": {
        "path": "/transcript",
        "response_path": ["text"],
    },
}

DEFAULTS = {
    "server": {"host": "127.0.0.1", "port": 8765},
    "transcription": {
        "provider": "none",       # none | whisper-local | any base_url provider
        "language": "auto",
        "model": "",
        "base_url": "",
        "api_key_env": "",
        "response_format": "json",
        "chain": [],          # ordered provider names; empty = use the flat fields above
        "providers": {},      # name -> {base_url, model, api_key_env, ...}
    },
}

# What `wc setup` asks, in order. The agent reads this and asks the user;
# the answers become the config file. Nothing is hardcoded to one vendor.
SETUP_QUESTIONS = [
    {"key": "transcription.language", "ask": "Which language do you speak most? (default: auto)"},
    {"key": "transcription.provider",
     "ask": "How should recordings be transcribed? local whisper model, a service "
            "speaking the audio-transcriptions API, or none"},
    {"key": "transcription.base_url",
     "ask": "If a service: what is its base URL? (leave empty for a local server)",
     "when": {"transcription.provider": {"not_in": ["none", "whisper-local"]}}},
    {"key": "transcription.api_key_env",
     "ask": "If it needs a key: which environment variable holds it? "
            "(the key itself is never written to the config)",
     "when": {"transcription.provider": {"not_in": ["none", "whisper-local"]}}},
    {"key": "transcription.model",
     "ask": "If a service: which model name should be sent?",
     "when": {"transcription.provider": {"not_in": ["none", "whisper-local"]}}},
]


@dataclass
class Config:
    server: dict = field(default_factory=lambda: dict(DEFAULTS["server"]))
    transcription: dict = field(default_factory=lambda: dict(DEFAULTS["transcription"]))
    adapters: dict = field(default_factory=lambda: {k: dict(v) for k, v in ADAPTERS.items()})
    routing: dict = field(default_factory=lambda: {"type": "naive", "base_url": "",
                                                   "api_key_env": "", "model": ""})
    routes: list = field(default_factory=list)
    destinations: dict = field(default_factory=dict)

    def provider_spec(self, name: str = "") -> dict:
        """The one contract: base_url + key from env + adapter tweaks if any."""
        if name:
            spec = dict(self.transcription.get("providers", {}).get(name, {}))
            spec.setdefault("model", self.transcription.get("model", ""))
            spec.setdefault("response_format", self.transcription.get("response_format", "json"))
            spec.setdefault("language", self.transcription.get("language", "auto"))
        else:
            spec = dict(self.transcription)
        adapter = self.adapters.get(spec.get("provider", ""), {})
        spec.update({k: v for k, v in adapter.items() if k not in spec or not spec[k]})
        spec["api_key"] = os.environ.get(spec.get("api_key_env") or "", "")
        return spec


def parse(text: str) -> Config:
    data = tomllib.loads(text)
    cfg = Config()
    cfg.server.update(data.get("server", {}))
    cfg.transcription.update(data.get("transcription", {}))
    cfg.routing.update(data.get("routing", {}))
    cfg.routes = data.get("routes", [])
    cfg.destinations = data.get("destinations", {})
    overrides = data.get("transcription", {}).get("adapters", {})
    for name, spec in overrides.items():
        cfg.adapters.setdefault(name, {}).update(spec)
    return cfg


def load(path: Path | None = None) -> Config:
    path = path or config_path()
    if not path.exists():
        return Config()
    return parse(path.read_text())


def to_toml(cfg: Config) -> str:
    lines: list[str] = []

    def scalar(value) -> str:
        if isinstance(value, bool):
            return "true" if value else "false"
        if isinstance(value, (int, float)):
            return str(value)
        if isinstance(value, list) and all(not isinstance(v, dict) for v in value):
            return "[" + ", ".join(scalar(v) for v in value) + "]"
        return json.dumps(value)

    def table(prefix: str, body: dict) -> None:
        simple = {k: v for k, v in body.items() if not isinstance(v, dict)}
        nested = {k: v for k, v in body.items() if isinstance(v, dict)}
        if prefix:
            lines.append(f"[{prefix}]")
        for k, v in simple.items():
            if v == "" or v is None:
                continue
            lines.append(f"{k} = {scalar(v)}")
        if prefix and simple:
            lines.append("")
        for k, v in nested.items():
            table(f"{prefix}.{k}" if prefix else k, v)

    table("server", cfg.server)
    table("transcription", cfg.transcription)
    table("routing", cfg.routing)
    for route in cfg.routes:
        lines.append("[[routes]]")
        for k, v in route.items():
            lines.append(f"{k} = {scalar(v)}")
        lines.append("")
    for name, dest in cfg.destinations.items():
        table(f"destinations.{name}", dest)
    for name, spec in cfg.adapters.items():
        table(f"transcription.adapters.{name}", spec)
    return "\n".join(lines).strip() + "\n"


def save(cfg: Config, path: Path | None = None) -> None:
    path = path or config_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(to_toml(cfg))
    path.chmod(0o600)


def set_value(cfg: Config, dotted: str, value: str) -> None:
    """wc config set transcription.language en"""
    section, _, key = dotted.rpartition(".")
    target = {"transcription": cfg.transcription, "server": cfg.server}.get(section)
    if target is None:
        raise KeyError(f"unknown section: {section}")
    target[key] = json.loads(value) if value[:1] in "[{" else value


def next_question(cfg: Config) -> dict | None:
    """The first setup question whose `when` currently holds."""
    answers = {"transcription": cfg.transcription, "server": cfg.server}
    for q in SETUP_QUESTIONS:
        if q["key"].split(".", 1)[1] and answers[q["key"].split(".")[0]].get(q["key"].split(".")[1]) not in ("", None):
            continue
        cond = q.get("when", {}).get(q["key"])
        if cond:
            current = answers[q["key"].split(".")[0]].get(q["key"].split(".")[1])
            not_in = cond.get("not_in") if isinstance(cond, dict) else cond
            if not_in and current in not_in:
                continue
        return q
    return None


def as_json(cfg: Config) -> dict:
    spec = cfg.provider_spec
    if spec.get("api_key"):
        spec["api_key"] = "<set>"   # never print the secret
    return {"server": cfg.server, "transcription": spec, "adapters": cfg.adapters}
